sap.ui.require([
  "sap/ui/table/Table", "sap/ui/table/Column", "sap/ui/table/rowmodes/Fixed",
  "sap/m/Text", "sap/ui/model/json/JSONModel"
], function (Table, Column, FixedRowMode, Text, JSONModel) {
  var oModel = new JSONModel({
    products: [
      { name: "노트북", price: 1200 }, { name: "모니터", price: 300 },
      { name: "키보드", price: 50 },   { name: "마우스", price: 30 },
      { name: "헤드셋", price: 80 }
    ]
  });

  var oTable = new Table({
    selectionMode: "Single",
    rowMode: new FixedRowMode({ rowCount: 3 }),
    columns: [
      new Column({ label: new Text({ text: "상품명" }), template: new Text({ text: "{name}", wrapping: false }) }),
      new Column({ label: new Text({ text: "가격" }),   template: new Text({ text: "{price}", wrapping: false }) })
    ]
  });

  oTable.setModel(oModel);
  oTable.bindRows("/products");   // rows 는 바인딩으로만 사용
  oTable.placeAt("content");
});

sap.ui.require([
  "sap/ui/table/Table", "sap/ui/table/Column", "sap/ui/table/rowmodes/Fixed",
  "sap/m/Text", "sap/ui/model/json/JSONModel"
], function (Table, Column, FixedRowMode, Text, JSONModel) {
  var oTable = new Table({
    selectionMode: "MultiToggle",
    rowMode: new FixedRowMode({ rowCount: 3 }),
    columns: [ new Column({ label: new Text({ text: "이름" }), template: new Text({ text: "{name}", wrapping: false }) }) ]
  });
  oTable.setModel(new JSONModel({ rows: [ { name: "가" }, { name: "나" }, { name: "다" } ] }));
  oTable.bindRows("/rows");

  oTable.attachRowSelectionChange(function (oEvent) {
    var aIdx = oTable.getSelectedIndices();      // 선택된 행의 인덱스 배열
    console.log("선택된 행:", aIdx, "변경 행:", oEvent.getParameter("rowIndices"));
  });

  oTable.placeAt("content");
});
